# Helper function to check if a string contains any of the given keywords (case-insensitive)
contains_string_ignore_case(str, keywords) {
    is_string(str)
    lower_str := lower(str)
    keyword := keywords[_]
    contains(lower_str, lower(keyword))
}

# Helper function to check if a value is empty or null
is_empty_or_null(value) {
    value.ir_type == "String"
    value.value == ""
} else {
    value.ir_type == "Null"
} else {
    value.ir_type == "Undef"
}

# Helper function to check if a string contains a substring (case-insensitive)
contains(str, substr) {
    regex.match(sprintf("(?i).*%s.*", [substr]), str)
}

